  let img-box = if img != "" {
    box(
      width: 7.8cm,
      height: 5.5cm,
      clip: true,
      radius: 4pt,
      image(img, width: 100%, height: 100%, fit: cover)
    )
  } else {
    box(
      width: 7.8cm,
      height: 5.5cm,
      fill: accent.lighten(88%),
      stroke: (thickness: 0.5pt, paint: accent.lighten(50%)),
      radius: 4pt,
      align(center + horizon)[
        #text(size: 9pt, fill: accent)[📍 景點照片]
      ]
    )
  }
  let cost-line = if cost != "" {
    [#v(4pt)
    #box(radius: 3pt, fill: accent.lighten(80%), inset: (x: 6pt, y: 2pt))[
      #text(size: 7.5pt, weight: 700, fill: accent)[#cost]
    ]]
  } else { [] }
  let prose-col = [
    #text(size: 10pt, weight: 800, fill: accent)[#title]
    #v(3pt)
    #box(width: 1.2cm, height: 1.5pt, fill: accent, radius: 0.75pt)
    #v(5pt)
    #text(size: 9pt, fill: C-text)[#description]
    #cost-line
  ]
  if image-left {
    grid(columns: (7.8cm, 1fr), column-gutter: 14pt, align: (top, top),
      img-box,
      prose-col,
    )
  } else {
    grid(columns: (1fr, 7.8cm), column-gutter: 14pt, align: (top, top),
      prose-col,
      img-box,
    )
  }
}

